def snapshot(self) -> dict:
    with self.engine.connect() as connection:
        rows = [dict(row) for row in connection.execute(text(
            "SELECT id,owner_id,filename,size,state,revision,build_id,journal FROM files")).mappings()]
        relations = [dict(row) for row in connection.execute(text(
            "SELECT file_id,recipient_id,shared_by FROM shares ORDER BY recipient_id")).mappings()]
        content_hashes = {row.id: hashlib.sha256(row.content).hexdigest()
                          for row in connection.execute(text("SELECT id,content FROM files"))}
    for row in rows:
        row["context"] = {
            "owner_id": row["owner_id"], "filename": row["filename"], "size": row["size"],
            "recipient_ids": [s["recipient_id"] for s in relations if s["file_id"] == row["id"]],
            "sha256": content_hashes[row["id"]],
        }
        row["journal"] = json.loads(row["journal"])
    return {"files": rows, "shares": relations}

